from __future__ import annotations
import base64, shutil
from datetime import datetime
from pathlib import Path

TARGET="alliance_exception_forensics_v424.py"
REG="alliance_optional_property_modules.py"
DATA=""

def chk(p):
    compile(p.read_text(encoding="utf-8"), str(p), "exec")

def main():
    r=Path.cwd()
    required=[
        TARGET,
        "alliance_automation_grammar_rescue_v423.py",
        "alliance_automation_closure_v422.py",
        "alliance_automation_truth_escalator_v421.py",
        "alliance_automation_machine_v420.py",
        "alliance_cre_championship_v410.py",
        "alliance_cre_academy_v402.py",
        REG,
    ]
    missing=[x for x in required if not (r/x).exists()]
    if missing:
        raise SystemExit("Missing cumulative files: "+", ".join(missing))

    v421=(r/"alliance_automation_truth_escalator_v421.py").read_text(encoding="utf-8")
    required_symbols=["def _judges(","def judge_cre_graph(","def judge_intent_hierarchy(","v420.judge_evidence","v420.judge_critic"]
    absent=[s for s in required_symbols if s not in v421]
    if absent:
        raise SystemExit("Current v421 API differs; refusing blind update: "+repr(absent))

    current=(r/TARGET).read_text(encoding="utf-8")
    if "v421.judge_evidence(raw)" not in current and "v421._judges(engine,raw)" not in current:
        raise SystemExit("Unexpected v424 diagnostics shape; refusing blind overwrite.")

    backup=r/f"{TARGET}.before-hotfix2-{datetime.now().strftime('%Y%m%d-%H%M%S')}.bak"
    shutil.copy2(r/TARGET,backup)
    (r/TARGET).write_text(base64.b64decode(DATA).decode(),encoding="utf-8")

    chk(r/TARGET); chk(r/REG)

    final=(r/TARGET).read_text(encoding="utf-8")
    if "v421._judges(engine,raw)" not in final:
        raise SystemExit("4.2.4.2 verification failed.")
    if "v421.judge_evidence(raw)" in final:
        raise SystemExit("Obsolete v421 API call still present.")

    print("Foundation 4.2.4.2 hotfix installed")
    print("Fixed: forensic module now calls v421._judges(engine, raw)")
    print("Verified current v421 judge registry before replacement")
    print("Frozen V4 student unchanged")
    print("Production/WhatsApp/Gold writes: 0")
    print("Dashboard remains: /property-brain/automation-v424")
    print("Backup:",backup)

if __name__=="__main__":
    main()
